import subprocess,json,os
from pathlib import Path
src=Path('/srv/lowcost-europa')
parent=Path('/srv/projects')
dst=parent/'lowcost-europa'
def cmd(a,t=15):
 return subprocess.run(a,capture_output=True,text=True,timeout=t)
def live(s):
 return cmd(['systemctl','is-active',s+'.service'],8).stdout.strip()
def jlist():
 r=cmd(['pm2','jlist'],12)
 if r.returncode:raise RuntimeError('PM2 unavailable')
 return {a.get('name'):(a.get('pm2_env') or {}).get('status') for a in json.loads(r.stdout)}
critical=['lowcost-europa','pink-iptv-backend','pink-vpn','fadego-staging','pm2-root','nginx','postgresql@16-main','ssh']
baseline={x:live(x) for x in critical}
if any(s!='active' for s in baseline.values()):raise RuntimeError('Services not active preflight')
if any(jlist().get(x)!='online' for x in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Telegram not online')
if not src.is_dir() or src.is_symlink() or not parent.is_dir() or dst.exists() or dst.is_symlink():raise RuntimeError('Paths unexpectedly changed')
r=cmd(['git','-C',str(src),'remote','get-url','origin'])
if r.returncode or 'martaxi-boss/lowcost-europa' not in r.stdout:raise RuntimeError('Wrong origin')
r=cmd(['git','-C',str(src),'status','--porcelain','--untracked-files=no'])
if r.returncode:raise RuntimeError('Git status failure')
original_status=r.stdout
print('GIT_BEFORE_COUNT='+str(len(original_status.splitlines())))
sz=cmd(['du','-x','-s','-B1',str(src)],45)
if sz.returncode:raise RuntimeError('Size unknown')
bytes_pre=int(sz.stdout.split()[0])
inode=src.stat().st_ino
pidquery=cmd(['systemctl','show','lowcost-europa.service','--no-pager','-p','MainPID','-p','WorkingDirectory'],12)
info=dict(line.split('=',1) for line in pidquery.stdout.splitlines() if '=' in line)
oldpid=info.get('MainPID')
if info.get('WorkingDirectory')!=str(src) or not oldpid or oldpid=='0':raise RuntimeError('Unit mismatch')
moved=False
try:
 src.rename(dst);moved=True
 src.symlink_to(dst,target_is_directory=True)
 if src.resolve()!=dst or not src.is_symlink() or dst.stat().st_ino!=inode:raise RuntimeError('Root or compatibility link mismatch')
 p=cmd([str(dst/'.venv/bin/python'),'-c','import sys; assert sys.version_info.major==3'],15)
 if p.returncode:raise RuntimeError('Python not executable at canonical path')
 after1=cmd(['git','-C',str(dst),'status','--porcelain','--untracked-files=no'],18)
 after2=cmd(['git','-C',str(dst),'status','--porcelain','--untracked-files=no'],18)
 if after1.returncode or after2.returncode or after2.stdout!=original_status:
  print('GIT_AFTER_FIRST_FILES='+str(after1.stdout.splitlines()[:25]))
  print('GIT_AFTER_SECOND_FILES='+str(after2.stdout.splitlines()[:25]))
  print('GIT_STATUS_ERROR_CODES='+str(after1.returncode)+','+str(after2.returncode))
  raise RuntimeError('Tracked project changed or Git sees a move-dependent change')
 du=cmd(['du','-x','-s','-B1',str(dst)],45)
 if du.returncode or int(du.stdout.split()[0])!=bytes_pre:raise RuntimeError('Size mismatch')
 newpid=cmd(['systemctl','show','lowcost-europa.service','-p','MainPID','--no-pager'],9).stdout.strip()
 if newpid!='MainPID='+oldpid:raise RuntimeError('Service PID changed')
 for name,state in baseline.items():
  if live(name)!=state:raise RuntimeError('Protected service changed: '+name)
 if any(jlist().get(x)!='online' for x in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Bot stopped')
except Exception:
 if src.is_symlink() and src.resolve()==dst:src.unlink()
 if moved and dst.is_dir() and not src.exists():dst.rename(src)
 print('LOWCOST_ROLLBACK=APPLIED')
 raise
print('LOWCOST_NEW_PHYSICAL_PATH='+str(dst))
print('LOwCOST_OLD_SYMLINK='+str(src))
print('BYTES_MOVED='+str(bytes_pre))
print('LOWCOST_PID_UNCHANGED='+str(oldpid))
print('TRACKED_GIT_UNCHANGED=YES')
print('SERVICE_AND_BOTS=ACTIVE')
print('DISK_SPACE_FREED=0')
print('LOWCOST_CANONICAL_MOVE=PASS')
PY
